"""Standalone local review: original RGB, estimated skeletons and measured errors."""
import json

def write_view(path,data):
 html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GlobalPose 母關節壓力測試</title>
<style>body{margin:0;background:#101824;color:#eaf1fa;font:15px system-ui}main{max-width:1400px;margin:auto;padding:25px}h1{font-size:25px}p{color:#b9c8da;line-height:1.7}button,select,input{padding:8px;background:#223147;color:white;border:1px solid #526477;border-radius:5px}canvas{width:100%;background:#182335;border-radius:8px}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.controls input{flex:1}.grid{display:grid;grid-template-columns:280px 1fr;gap:15px;margin-top:15px}video{width:100%;border-radius:8px}table{width:100%;border-collapse:collapse;margin-top:16px;font-size:13px}td,th{text-align:left;border-bottom:1px solid #344359;padding:9px}.bad{color:#ffad9e}.good{color:#91ddbb}small{color:#b9c8da}details{margin-top:20px}a{color:#8dcaff}@media(max-width:800px){.grid{grid-template-columns:1fr}video{max-height:300px}}</style>
<main><h1>GlobalPose：母關節推導壓力測試</h1><p>六顆虛擬 IMU，60 Hz；真實 MediaPipe 對合成 RGB 辨識，10 Hz。左圖為輸入影像；骨架依序為構造真值、GlobalPose、正式關節約束＋IMU、影像融合。滑鼠拖曳骨架可轉視角。</p>
<div class="controls"><button id="play">播放</button><select id="case"></select><select id="mode"><option value="occluded">部分＋完全遮擋</option><option value="clear">無外加遮擋</option></select><input id="time" type="range" min="0" step="1"><span id="stamp"></span></div>
<div class="grid"><div><video id="video" muted playsinline preload="metadata"></video><small>這是渲染後實際送入辨識器的 RGB，沒有用真值代替影像關節。</small></div><canvas id="scene" width="1100" height="540"></canvas></div>
<p id="stats"></p><h2>母關節旋轉誤差</h2><small>單位：度。統計每段最後 3 秒；含大腿、脊椎、鎖骨、上臂。MPJPE 為骨盆相對位置誤差，不做 Procrustes 對齊。只代表這組合成動作。</small><table id="table"></table>
<details open><summary>可觀測性與測試邊界</summary><p id="ambiguity"></p><ul id="limits"></ul></details><p><a href="GlobalPose-complex-report.json">完整數據</a> · <a href="https://github.com/Xinyu-Yi/GlobalPose">GlobalPose 官方程式</a></p></main>
<script>const data=__DATA__, $=x=>document.getElementById(x), canvas=$('scene'),ctx=canvas.getContext('2d');let frame=0,playing=false,last=0,yaw=.15,drag=null;const methods=['GlobalPose','GP_IMU'];
for(let k=0;k<data.cases.length;k++)$('case').add(new Option(data.cases[k][1],k));$('time').max=data.truth.length-1;
function modeName(){return $('mode').value==='clear'?'Hybrid_clear':'Hybrid_occluded'}function project(p,c){let x=p[0]*Math.cos(yaw)+p[2]*Math.sin(yaw),z=-p[0]*Math.sin(yaw)+p[2]*Math.cos(yaw);return [c+x*175*(3.8/(3.8-z)),310-p[1]*175*(3.8/(3.8-z))]}
function body(points,c,color,alpha=1){ctx.strokeStyle=color;ctx.fillStyle=color;ctx.globalAlpha=alpha;ctx.lineWidth=4;for(let j=1;j<24;j++){const a=project(points[j],c),b=project(points[data.parents[j]],c);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}for(const j of data.summary.parent_joints){const p=project(points[j],c);ctx.beginPath();ctx.arc(...p,5,0,7);ctx.fill()}ctx.globalAlpha=1}
function axes(points,g,c){for(const j of [1,2,9,16,17]){const a=project(points[j],c);for(let k=0;k<3;k++){const end=points[j].map((v,m)=>v+.14*g[j][m][k]),b=project(end,c);ctx.strokeStyle=['#ff7e80','#81e7a8','#91a7ff'][k];ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}}}
function draw(){ctx.clearRect(0,0,1100,540);const names=['構造真值','GlobalPose','關節約束＋IMU','＋影像修正'],keys=[null,'GlobalPose','GP_IMU',modeName()];for(let k=0;k<4;k++){const c=140+275*k;ctx.fillStyle='#b9c8da';ctx.font='16px system-ui';ctx.textAlign='center';ctx.fillText(names[k],c,30);if(k)body(data.truth[frame],c,'#8390a4',.25);body(k?data.methods[keys[k]][frame]:data.truth[frame],c,k?'#71cffa':'#91ddbb');axes(k?data.methods[keys[k]][frame]:data.truth[frame],k?data.globals[keys[k]][frame]:data.truth_globals[frame],c);if(k){ctx.fillStyle='#f3c68c';ctx.fillText(data.errors[keys[k]][frame].toFixed(1)+'°',c,510)}}$('stamp').textContent=(frame/data.fps).toFixed(2)+' s';$('time').value=frame;const t=frame/data.fps,phase=t%data.seconds;$('stats').textContent=(phase<2?'共同 T-pose 暖機':phase<3?'平滑進入動作':$('mode').value==='occluded'&&phase>=4.3&&phase<5?'完全遮擋':$('mode').value==='occluded'&&phase>=3&&phase<4.1?'部分遮擋':'動作／恢復')+'；灰色骨架為真值。大圓點標示母關節；RGB 短線顯示旋轉座標軸，避免漏看純扭轉。';}
function syncVideo(){const t=frame/data.fps;if(Math.abs($('video').currentTime-t)>.09)$('video').currentTime=t}
function table(){const rows=data.summary.cases;let html='<tr><th>動作</th><th>GlobalPose</th><th>＋約束／IMU</th><th>＋影像（清楚）</th><th>＋影像（遮擋）</th><th>清楚影像偵測</th></tr>';for(const r of rows){html+='<tr><td>'+r.label+'</td>';for(const n of ['GlobalPose','GP_IMU','Hybrid_clear','Hybrid_occluded'])html+='<td>'+r.methods[n].parent_deg.mean.toFixed(1)+'°<br><small>P95 '+r.methods[n].parent_deg.p95.toFixed(1)+'°</small></td>';html+='<td>'+r.clear_camera.person_detections+'/'+r.clear_camera.frames+'</td></tr>'}$('table').innerHTML=html}
$('case').onchange=()=>{frame=Math.round(Number($('case').value)*data.seconds*data.fps);syncVideo();draw()};$('mode').onchange=()=>{$('video').src='GlobalPose-complex-'+$('mode').value+'.mp4';$('video').onloadedmetadata=syncVideo;draw()};$('time').oninput=()=>{frame=Number($('time').value);syncVideo();draw()};$('play').onclick=()=>{playing=!playing;last=0;$('play').textContent=playing?'暫停':'播放'};
canvas.onpointerdown=e=>{drag=e.clientX;canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag!==null){yaw+=(e.clientX-drag)*.01;drag=e.clientX;draw()}};canvas.onpointerup=()=>drag=null;
function tick(t){if(playing){if(!last)last=t;if(t-last>=1000/data.fps){frame=(frame+1)%data.truth.length;last=t;syncVideo();draw()}}requestAnimationFrame(tick)}
const a=data.summary.ambiguity;$('ambiguity').textContent='剛體反例：上臂相差 '+a.parent_separation_deg.toFixed(1)+'°，六個被量測骨段的方向與所有關節中心卻相同。因此同一估計至少在其中一個姿態錯 '+a.worst_case_parent_error_lower_bound_deg+'°。這是剛體骨架的可觀測性反例，不是經解剖驗證的人體動作，也未聲稱皮膚表面感測器加速度完全一致。只看關節中心的相機無法識別純軸向扭轉。';for(const line of data.summary.limitations){let li=document.createElement('li');li.textContent=line;$('limits').appendChild(li)}table();$('mode').onchange();draw();requestAnimationFrame(tick);</script></html>'''
 path.write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
